reference_solution:
def count_power_of_two_meals(deliciousness):
 counts=Counter();answer=0
 for value in deliciousness:
  for power in (1<<bit for bit in range(22)):answer+=counts[power-value]
  counts[value]+=1
 return answer%1000000007

